import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen2Test {

    @Test
    public void testRevertWithStandardLine() {
        // Setup a line from (0,0,0) to (1,1,1)
        Vector3D p1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D p2 = new Vector3D(1.0, 1.0, 1.0);
        Line originalLine = new Line(p1, p2);

        // Execute revert
        Line revertedLine = originalLine.revert();

        // Verify non-nullity
        assertNotNull("Reverted line should not be null", revertedLine);

        // Verify that the direction is reversed
        // Original direction is (1,1,1) normalized
        Vector3D originalDir = originalLine.getDirection();
        Vector3D revertedDir = revertedLine.getDirection();

        assertEquals("Reverted direction should be the negative of the original direction",
                0.0, originalDir.dotProduct(revertedDir) + 1.0, 1e-10);

        // Verify similarity (a line and its reverse are the same line in space)
        assertTrue("The reversed line should be similar to the original line",
                originalLine.isSimilarTo(revertedLine));

        // Verify that the origin has changed (it should be a point on the original line)
        // In Apache Commons Math, revert() effectively flips the direction vector.
        // Since the constructor Line(Line) is used, we check if the geometric properties hold.
        assertEquals("The distance from a point on the line to the origin should remain consistent",
                originalLine.getAbscissa(originalLine.getOrigin()),
                revertedLine.getAbscissa(revertedLine.getOrigin()), 1e-10);
    }

    @Test
    public void testRevertWithNegativeDirection() {
        // Setup a line with a pre-existing negative direction
        Vector3D p1 = new Vector3D(10.0, 0.0, 0.0);
        Vector3D p2 = new Vector3D(5.0, 0.0, 0.0);
        Line originalLine = new Line(p1, p2);

        Line revertedLine = originalLine.revert();

        // Original direction is (-1, 0, 0)
        // Reverted direction should be (1, 0, 0)
        Vector3D originalDir = originalLine.getDirection();
        Vector3D revertedDir = revertedLine.getDirection();

        assertEquals("Direction component X should be flipped", 
                -originalDir.getX(), revertedDir.getX(), 1e-10);
        assertTrue("Reverted line should be similar to original", 
                originalLine.isSimilarTo(revertedLine));
    }

    @Test
    public void testRevertIdentity() {
        // Testing if revert().revert() returns a line similar to the original
        Vector3D p1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D p2 = new Vector3D(4.0, 5.0, 6.0);
        Line originalLine = new Line(p1, p2);

        Line doubleReverted = originalLine.revert().revert();

        assertTrue("Double revert should be similar to original line",
                originalLine.isSimilarTo(doubleReverted));

        // Direction should be identical after two reverts
        assertEquals("Direction should be the same after two reverts",
                originalLine.getDirection(), doubleReverted.getDirection());
    }
}
